def _sync_from_file(self) -> None:
    """Pull in anything written directly to the real file descriptor
    (for example by a subprocess whose ``stdout``/``stderr`` was set
    to this stream) so it also ends up in this ``BytesIO``.
    """
    pos = self._file.tell()
    self._file.seek(self.tell())
    data = self._file.read()
    self._file.seek(pos)
    if data:
        self.copy_to.write(data)
        io.BytesIO.write(self, data)

